describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against the original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both policies get the full 1000, results summed: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for non-positive subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child discounts to 0 before summing", () => {
      // A custom policy that returns negative
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const fixed = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, fixed],
        "sum",
      );
      // -50 clamped to 0, plus 100 = 100
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts in sum mode = 120% — returned raw, Cart clamps later
      const p1 = new PercentageDiscountPolicy(60);
      const p2 = new PercentageDiscountPolicy(60);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // 60% of 1000 = 600 each → sum = 1200
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to the remaining subtotal after previous discounts", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new PercentageDiscountPolicy(10); // 10% of 900 = 90
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("cannot exceed the subtotal in chain mode", () => {
      const p1 = new PercentageDiscountPolicy(50); // 50% of 1000 = 500
      const p2 = new PercentageDiscountPolicy(50); // 50% of 500 = 250
      const p3 = new PercentageDiscountPolicy(50); // 50% of 250 = 125
      const composite = new CompositeDiscountPolicy([p1, p2, p3], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(875);
    });

    it("returns 0 for non-positive subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 and caps at remaining", () => {
      const negativePolicy = { computeDiscountCents: () => -30 };
      const fixed = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, fixed],
        "chain",
      );
      // negative clamped to 0, remaining still 500; fixed 200 → total 200
      expect(composite.computeDiscountCents(500)).toBe(200);
    });

    it("ordering matters in chain mode", () => {
      // FixedAmount first, then percentage
      const fixed = new FixedAmountDiscountPolicy(200);
      const pct = new PercentageDiscountPolicy(10);
      const compositeA = new CompositeDiscountPolicy([fixed, pct], "chain");
      // fixed 200 off 1000 = remaining 800, 10% of 800 = 80 → total 280
      expect(compositeA.computeDiscountCents(1000)).toBe(280);

      // Percentage first, then fixed
      const compositeB = new CompositeDiscountPolicy([pct, fixed], "chain");
      // 10% of 1000 = 100, remaining 900, fixed 200 → total 300
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const p1 = new FixedAmountDiscountPolicy(100);
    const p2 = new FixedAmountDiscountPolicy(200);
    const composite = new CompositeDiscountPolicy([p1, p2]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

