      cart.add(makeProduct({ id: "a" }), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("ghost", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 2);
      cart.add(makeProduct({ id: "b" }), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that cannot mutate internal state", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 0;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents × quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2); // 1000
      cart.add(makeProduct({ id: "b", unitPriceCents: 300 }), 3); // 900
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1900);
    });

    it("applies discount, tax on discounted subtotal, then shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 1);

      const t = cart.totals();

      // subtotal = 1000
      expect(t.subtotalCents).toBe(1000);
      // discount = 200 (clamped into [0, 1000])
      expect(t.discountCents).toBe(200);
      // tax called with discounted subtotal (1000 - 200 = 800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(t.taxCents).toBe(80);
      // shipping called with lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(t.shippingCents).toBe(500);
      // total = discountedSubtotal + tax + shipping = 800 + 80 + 500
      expect(t.totalCents).toBe(1380);
    });

    it("clamps discount to [0, subtotal]", () => {
      // Discount returns more than subtotal
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 9999,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(500);
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
      expect(t.totalCents).toBe(500);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => -50,
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
      const cart = new Cart();
      cart.add(makeProduct({ unitPriceCents: 1500 }), 2);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(3000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(3000);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 2);
      cart.add(makeProduct({ id: "b", unitPriceCents: 500 }), 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2500);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1200) // a: was 1000 → 1200
          .mockResolvedValueOnce(600), // b: was 500 → 600
      };
      const result = await cart.checkout({ priceFetcher });
      // subtotal after refresh: 1200*2 + 600*1 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1200);
      expect(result.lines[1]!.product.unitPriceCents).toBe(600);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(2);
        expect(ie.message).toBe("sold out");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // requested 2, only 1 available
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.available).toBe(1);
        expect(ie.requested).toBe(2);
      }
    });

    it("passes inventory check when everything is available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2500);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US-CA" });
      cart.add(makeProduct({ id: "x", unitPriceCents: 1000 }), 1);
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 1000, no discount, tax = floor(1000 * 0.1) = 100
      expect(result.totals.taxCents).toBe(100);
      expect(result.totals.totalCents).toBe(1100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("composes discount + async tax + shipping", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 300,
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "US",
      });
      cart.add(makeProduct({ id: "x", unitPriceCents: 2000 }), 1);
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=2000, discount=500 (clamped), discounted=1500
      // tax = floor(1500 * 0.1) = 150, shipping=300
      // total = 1500 + 150 + 300 = 1950
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(150);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(1950);
    });

    it("propagates priceFetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const c = new Cart();
      c.add(makeProduct({ unitPriceCents: 1000 }), 1);
      await expect(c.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("generates default InventoryError message with available quantity", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          // no reason → default message
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.message).toContain("a"); // product id
      }
    });

    it("generates default InventoryError message without availableQuantity", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          // no availableQuantity, no reason
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.available).toBeUndefined();
      }
    });

    it("runs priceFetcher before inventoryChecker", async () => {
      const callOrder: string[] = [];
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation(async () => {
          callOrder.push("price");
          return 1000;
        }),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockImplementation(async () => {
          callOrder.push("inventory");
          return { available: true };
        }),
      };
      await cart.checkout({ priceFetcher, inventoryChecker });
      // All price fetches happen before any inventory check
      const firstInventory = callOrder.indexOf("inventory");
      const lastPrice = callOrder.lastIndexOf("price");
      expect(lastPrice).toBeLessThan(firstInventory);
    });
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([
    [0, 0],
    [1000, 0],
    [-500, 0],
    [999999, 0],
  ])("computeDiscountCents(%i) returns %i", (subtotal, expected) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(expected);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [101, "over 100"],
      [NaN, "NaN"],
      [Infinity, "Infinity"],
    ])("rejects %d (%s)", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
    });

    it.each([0, 50, 100])("accepts valid percent %d", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      // [percent, subtotal, expected]
      [10, 1000, 100],
      [10, 999, 99],
      [50, 1001, 500], // floors: 1001*50/100 = 500.5 → 500
      [100, 5000, 5000],
      [0, 5000, 0],
      [10, 0, 0],
      [10, -100, 0], // non-positive subtotal → 0
      [33, 100, 33],
      [15, 9999, 1499], // 9999*15/100 = 1499.85 → 1499
    ])(
      "%d%% of %i cents = %i",
      (percent, subtotal, expected) => {
        const policy = new PercentageDiscountPolicy(percent);
        expect(policy.computeDiscountCents(subtotal)).toBe(expected);
      },
    );
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([
      [-1, "negative"],
      [1.5, "non-integer"],
      [-100, "negative large"],
    ])("rejects %d (%s)", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it.each([0, 500, 10000])("accepts valid amount %d", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it.each([
      // [amountCents, subtotal, expected]
      [500, 1000, 500],
      [500, 300, 300], // capped at subtotal
      [500, 500, 500], // exact match
      [500, 0, 0],
      [500, -100, 0],
      [0, 1000, 0],
    ])(
      "fixed %i off %i = %i discount",
      (amountCents, subtotal, expected) => {
        const policy = new FixedAmountDiscountPolicy(amountCents);
        expect(policy.computeDiscountCents(subtotal)).toBe(expected);
      },
    );
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policies array", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all policies against the original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 100
      const p2 = new FixedAmountDiscountPolicy(200); // 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // Both policies get the full 1000, results summed: 100 + 200 = 300
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for non-positive subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
      expect(composite.computeDiscountCents(-100)).toBe(0);
    });

    it("clamps negative child discounts to 0 before summing", () => {
      // A custom policy that returns negative
      const negativePolicy = {
        computeDiscountCents: () => -50,
      };
      const fixed = new FixedAmountDiscountPolicy(100);
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, fixed],
        "sum",
      );
      // -50 clamped to 0, plus 100 = 100
      expect(composite.computeDiscountCents(500)).toBe(100);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // Two 60% discounts in sum mode = 120% — returned raw, Cart clamps later
      const p1 = new PercentageDiscountPolicy(60);
      const p2 = new PercentageDiscountPolicy(60);
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      // 60% of 1000 = 600 each → sum = 1200
      expect(composite.computeDiscountCents(1000)).toBe(1200);
    });
  });

  describe("chain mode", () => {
    it("applies each policy to the remaining subtotal after previous discounts", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new PercentageDiscountPolicy(10); // 10% of 900 = 90
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(190);
    });

    it("cannot exceed the subtotal in chain mode", () => {
      const p1 = new PercentageDiscountPolicy(50); // 50% of 1000 = 500
      const p2 = new PercentageDiscountPolicy(50); // 50% of 500 = 250
      const p3 = new PercentageDiscountPolicy(50); // 50% of 250 = 125
      const composite = new CompositeDiscountPolicy([p1, p2, p3], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(875);
    });

    it("returns 0 for non-positive subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("clamps negative child results to 0 and caps at remaining", () => {
      const negativePolicy = { computeDiscountCents: () => -30 };
      const fixed = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, fixed],
        "chain",
      );
      // negative clamped to 0, remaining still 500; fixed 200 → total 200
      expect(composite.computeDiscountCents(500)).toBe(200);
    });

    it("ordering matters in chain mode", () => {
      // FixedAmount first, then percentage
      const fixed = new FixedAmountDiscountPolicy(200);
      const pct = new PercentageDiscountPolicy(10);
      const compositeA = new CompositeDiscountPolicy([fixed, pct], "chain");
      // fixed 200 off 1000 = remaining 800, 10% of 800 = 80 → total 280
      expect(compositeA.computeDiscountCents(1000)).toBe(280);

      // Percentage first, then fixed
      const compositeB = new CompositeDiscountPolicy([pct, fixed], "chain");
      // 10% of 1000 = 100, remaining 900, fixed 200 → total 300
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });
  });

  it("defaults to sum mode when mode is omitted", () => {
    const p1 = new FixedAmountDiscountPolicy(100);
    const p2 = new FixedAmountDiscountPolicy(200);
    const composite = new CompositeDiscountPolicy([p1, p2]);
    expect(composite.computeDiscountCents(1000)).toBe(300);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

// Helper to create a product
function makeProduct(overrides: Partial<Product> = {}): Product {
  return {
    id: "p1",
    name: "Widget",
    unitPriceCents: 1000,
    ...overrides,
  };
}

function makeLine(
  productOverrides: Partial<Product> = {},
  quantity = 1,
): CartLine {
  return { product: makeProduct(productOverrides), quantity };
}

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate < 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects non-finite defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, Infinity)).toThrow(RangeError);
    });

    it("rejects out-of-range region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ US: -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0.0875, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });

    it("accepts zero and one as boundary rates", () => {
      expect(() => new RegionalTaxCalculator({ US: 0 }, 1)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it.each([
      // [taxable, region, expected]
      [10000, "US-CA", 875], // 10000 * 0.0875 = 875
      [10000, "FR", 2000],
      [10000, "GB", 500], // falls back to default 5%
      [10001, "US-CA", 875], // 10001 * 0.0875 = 875.0875 → 875
      [0, "US-CA", 0],
      [-100, "FR", 0],
    ])(
      "taxable=%i region=%s → %i cents",
      (taxable, region, expected) => {
        expect(calc.computeTaxCents(taxable, region)).toBe(expected);
      },
    );

    it("uses defaultRate=0 when no default is specified", () => {
      const c = new RegionalTaxCalculator({ US: 0.1 });
      expect(c.computeTaxCents(1000, "FR")).toBe(0);
    });
  });
});

