describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight × quantity across lines", () => {
    const lines: CartLine[] = [
      makeLine({ weightGrams: 200 }, 3), // 600
      makeLine({ weightGrams: 500 }, 2), // 1000
    ];
    expect(totalLineWeightGrams(lines)).toBe(1600);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      makeLine({}, 5), // no weight → 0
      makeLine({ weightGrams: 100 }, 2), // 200
    ];
    expect(totalLineWeightGrams(lines)).toBe(200);
  });
});

import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
  type WeightBracket,
} from "../src/shipping.ts";
import type { CartLine, Product } from "../src/product.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return {
    id: "p1",
    name: "Widget",
    unitPriceCents: 1000,
    ...overrides,
  };
}

function makeLine(
  productOverrides: Partial<Product> = {},
  quantity = 1,
): CartLine {
  return { product: makeProduct(productOverrides), quantity };
}

describe("FreeShippingCalculator", () => {
