});

describe("WeightBasedShippingCalculator", () => {
  const brackets: WeightBracket[] = [
    { upToGrams: 500, costCents: 300 },
    { upToGrams: 1000, costCents: 600 },
    { upToGrams: 5000, costCents: 1200 },
  ];

  describe("constructor validation", () => {
    it("rejects empty brackets", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with non-positive upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500.5, costCents: 100 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 500, costCents: 1.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 300 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 500, costCents: 300 }],
            10.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const calc = new WeightBasedShippingCalculator(brackets);

    it("returns 0 for empty cart", () => {
      expect(calc.computeShippingCents([], 5000)).toBe(0);
    });

    it("returns 0 when total weight is 0 (no weightGrams)", () => {
      const lines = [makeLine({}, 3)]; // no weightGrams → 0
      expect(calc.computeShippingCents(lines, 5000)).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      // 400g → first bracket (up to 500g) → 300
      const lines = [makeLine({ weightGrams: 400 }, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects boundary exactly at bracket limit", () => {
      // Exactly 500g → first bracket
      const lines = [makeLine({ weightGrams: 500 }, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(300);
    });

    it("selects next bracket when weight exceeds previous", () => {
      // 501g → second bracket (up to 1000g) → 600
      const lines = [makeLine({ weightGrams: 501 }, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(600);
    });

    it("selects highest bracket at its boundary", () => {
      const lines = [makeLine({ weightGrams: 5000 }, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("uses overflow (heaviest bracket) when weight exceeds all brackets", () => {
      // 6000g > 5000g → overflow defaults to last bracket cost (1200)
      const lines = [makeLine({ weightGrams: 6000 }, 1)];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("uses explicit overflowCostCents when specified", () => {
      const calcWithOverflow = new WeightBasedShippingCalculator(
        brackets,
        2000,
      );
      const lines = [makeLine({ weightGrams: 6000 }, 1)];
      expect(calcWithOverflow.computeShippingCents(lines, 5000)).toBe(2000);
    });

    it("sums weight across multiple lines and quantities", () => {
      // 2 × 300g + 1 × 500g = 1100g → third bracket (up to 5000g) → 1200
      const lines = [
        makeLine({ id: "a", weightGrams: 300 }, 2),
        makeLine({ id: "b", weightGrams: 500 }, 1),
      ];
      expect(calc.computeShippingCents(lines, 5000)).toBe(1200);
    });

    it("sorts brackets internally regardless of input order", () => {
      const unorderedBrackets: WeightBracket[] = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 1000, costCents: 600 },
      ];
      const c = new WeightBasedShippingCalculator(unorderedBrackets);
      const lines = [makeLine({ weightGrams: 400 }, 1)];
      expect(c.computeShippingCents(lines, 5000)).toBe(300);
    });
  });
});

import { describe, it, expect, vi } from "vitest";
import {
