describe("refreshPrices", () => {
  it("updates unitPriceCents from the fetcher", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn()
        .mockResolvedValueOnce(2000)
        .mockResolvedValueOnce(3000),
    };
    const lines: CartLine[] = [
      { product: makeProduct({ id: "a" }), quantity: 2 },
      { product: makeProduct({ id: "b" }), quantity: 1 },
    ];
    const refreshed = await refreshPrices(lines, fetcher);

    expect(refreshed).toHaveLength(2);
    expect(refreshed[0]!.product.unitPriceCents).toBe(2000);
    expect(refreshed[0]!.quantity).toBe(2);
    expect(refreshed[1]!.product.unitPriceCents).toBe(3000);
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("a");
    expect(fetcher.fetchPriceCents).toHaveBeenCalledWith("b");
  });

  it("preserves other product fields", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(500),
    };
    const lines: CartLine[] = [
      {
        product: makeProduct({ id: "x", name: "Gadget", weightGrams: 200 }),
        quantity: 1,
      },
    ];
    const refreshed = await refreshPrices(lines, fetcher);
    expect(refreshed[0]!.product.name).toBe("Gadget");
    expect(refreshed[0]!.product.weightGrams).toBe(200);
  });

  it("throws RangeError for negative fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(-1),
    };
    const lines: CartLine[] = [
      { product: makeProduct({ id: "bad" }), quantity: 1 },
    ];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("throws RangeError for non-integer fetched price", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(10.5),
    };
    const lines: CartLine[] = [
      { product: makeProduct({ id: "bad" }), quantity: 1 },
    ];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(RangeError);
  });

  it("handles empty lines array", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const refreshed = await refreshPrices([], fetcher);
    expect(refreshed).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });

  it("propagates fetcher rejection", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("network error")),
    };
    const lines: CartLine[] = [
      { product: makeProduct({ id: "a" }), quantity: 1 },
    ];
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow(
      "network error",
    );
  });
});

import { describe, it, expect, vi, beforeEach } from "vitest";
import { Cart, type CartConfig } from "../src/cart.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { Product, CartLine } from "../src/product.ts";
import type {
  PriceFetcher,
  InventoryChecker,
} from "../src/inventory.ts";
import { InventoryError } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

function makeProduct(overrides: Partial<Product> = {}): Product {
  return {
    id: "p1",
    name: "Widget",
    unitPriceCents: 1000,
    ...overrides,
  };
}

describe("Cart", () => {
  describe("add", () => {
    it("adds a new product to the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 2);
      expect(cart.itemCount).toBe(2);
    });

    it("merges quantity when adding the same product id", () => {
      const cart = new Cart();
      const product = makeProduct({ id: "a" });
      cart.add(product, 2);
      cart.add(product, 3);
      expect(cart.itemCount).toBe(5);
    });

    it("rejects non-positive quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 0)).toThrow(RangeError);
      expect(() => cart.add(makeProduct(), -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      expect(() => cart.add(makeProduct(), 1.5)).toThrow(RangeError);
    });

    it("rejects negative unitPriceCents", () => {
      const cart = new Cart();
      expect(
        () => cart.add(makeProduct({ unitPriceCents: -1 }), 1),
      ).toThrow(RangeError);
    });
  });

  describe("remove", () => {
    it("removes a product and returns true", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 1);
      expect(cart.remove("a")).toBe(true);
      expect(cart.itemCount).toBe(0);
    });

    it("returns false for unknown product id", () => {
      const cart = new Cart();
      expect(cart.remove("nonexistent")).toBe(false);
    });
  });

  describe("updateQuantity", () => {
    it("updates quantity for an existing product", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 3);
      cart.updateQuantity("a", 5);
      expect(cart.itemCount).toBe(5);
    });

    it("removes product when quantity is set to 0", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 3);
      cart.updateQuantity("a", 0);
      expect(cart.itemCount).toBe(0);
    });

    it("throws for unknown product id", () => {
      const cart = new Cart();
      expect(() => cart.updateQuantity("ghost", 1)).toThrow(
        "not in the cart",
      );
    });

    it("rejects negative quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 1);
      expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
    });

    it("rejects non-integer quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 1);
      expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
    });
  });

  describe("clear", () => {
    it("empties the cart", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a" }), 2);
      cart.add(makeProduct({ id: "b" }), 3);
      cart.clear();
      expect(cart.itemCount).toBe(0);
    });
  });

  describe("snapshot", () => {
    it("returns a deep copy that cannot mutate internal state", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2);
      const snap = cart.snapshot();
      snap[0]!.quantity = 999;
      snap[0]!.product.unitPriceCents = 0;
      expect(cart.itemCount).toBe(2);
      expect(cart.totals().subtotalCents).toBe(1000);
    });
  });

  describe("totals (pricing pipeline)", () => {
    it("computes subtotal as sum of unitPriceCents × quantity", () => {
      const cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 500 }), 2); // 1000
      cart.add(makeProduct({ id: "b", unitPriceCents: 300 }), 3); // 900
      const t = cart.totals();
      expect(t.subtotalCents).toBe(1900);
    });

    it("applies discount, tax on discounted subtotal, then shipping", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: vi.fn().mockReturnValue(200),
      };
      const taxCalculator: TaxCalculator = {
        computeTaxCents: vi.fn().mockReturnValue(80),
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: vi.fn().mockReturnValue(500),
      };
      const cart = new Cart({
        discountPolicy,
        taxCalculator,
        shippingCalculator,
        region: "US-CA",
      });
      cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 1);

      const t = cart.totals();

      // subtotal = 1000
      expect(t.subtotalCents).toBe(1000);
      // discount = 200 (clamped into [0, 1000])
      expect(t.discountCents).toBe(200);
      // tax called with discounted subtotal (1000 - 200 = 800)
      expect(taxCalculator.computeTaxCents).toHaveBeenCalledWith(800, "US-CA");
      expect(t.taxCents).toBe(80);
      // shipping called with lines and discounted subtotal
      expect(shippingCalculator.computeShippingCents).toHaveBeenCalledWith(
        expect.any(Array),
        800,
      );
      expect(t.shippingCents).toBe(500);
      // total = discountedSubtotal + tax + shipping = 800 + 80 + 500
      expect(t.totalCents).toBe(1380);
    });

    it("clamps discount to [0, subtotal]", () => {
      // Discount returns more than subtotal
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 9999,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(500);
      expect(t.totalCents).toBe(0);
    });

    it("clamps negative discount to 0", () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => -100,
      };
      const cart = new Cart({ discountPolicy });
      cart.add(makeProduct({ unitPriceCents: 500 }), 1);
      const t = cart.totals();
      expect(t.discountCents).toBe(0);
      expect(t.totalCents).toBe(500);
    });

    it("clamps negative tax to 0", () => {
      const taxCalculator: TaxCalculator = {
        computeTaxCents: () => -50,
      };
      const cart = new Cart({ taxCalculator });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().taxCents).toBe(0);
    });

    it("clamps negative shipping to 0", () => {
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => -100,
      };
      const cart = new Cart({ shippingCalculator });
      cart.add(makeProduct({ unitPriceCents: 1000 }), 1);
      expect(cart.totals().shippingCents).toBe(0);
    });

    it("defaults to NoDiscount, NoTax, FreeShipping, region US", () => {
      const cart = new Cart();
      cart.add(makeProduct({ unitPriceCents: 1500 }), 2);
      const t = cart.totals();
      expect(t.subtotalCents).toBe(3000);
      expect(t.discountCents).toBe(0);
      expect(t.taxCents).toBe(0);
      expect(t.shippingCents).toBe(0);
      expect(t.totalCents).toBe(3000);
    });

    it("returns all zeros for empty cart", () => {
      const cart = new Cart();
      const t = cart.totals();
      expect(t.subtotalCents).toBe(0);
      expect(t.totalCents).toBe(0);
    });
  });

  describe("checkout", () => {
    let cart: Cart;

    beforeEach(() => {
      cart = new Cart();
      cart.add(makeProduct({ id: "a", unitPriceCents: 1000 }), 2);
      cart.add(makeProduct({ id: "b", unitPriceCents: 500 }), 1);
    });

    it("returns totals and lines without collaborators", async () => {
      const result = await cart.checkout();
      expect(result.totals.subtotalCents).toBe(2500);
      expect(result.lines).toHaveLength(2);
    });

    it("refreshes prices via priceFetcher", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockResolvedValueOnce(1200) // a: was 1000 → 1200
          .mockResolvedValueOnce(600), // b: was 500 → 600
      };
      const result = await cart.checkout({ priceFetcher });
      // subtotal after refresh: 1200*2 + 600*1 = 3000
      expect(result.totals.subtotalCents).toBe(3000);
      expect(result.lines[0]!.product.unitPriceCents).toBe(1200);
      expect(result.lines[1]!.product.unitPriceCents).toBe(600);
    });

    it("throws InventoryError when item is unavailable", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.requested).toBe(2);
        expect(ie.message).toBe("sold out");
      }
    });

    it("throws InventoryError on partial-stock denial", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: true,
          availableQuantity: 1, // requested 2, only 1 available
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.productId).toBe("a");
        expect(ie.available).toBe(1);
        expect(ie.requested).toBe(2);
      }
    });

    it("passes inventory check when everything is available", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({ available: true }),
      };
      const result = await cart.checkout({ inventoryChecker });
      expect(result.totals.subtotalCents).toBe(2500);
      expect(inventoryChecker.check).toHaveBeenCalledTimes(2);
    });

    it("uses asyncTaxProvider for tax computation", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({ region: "US-CA" });
      cart.add(makeProduct({ id: "x", unitPriceCents: 1000 }), 1);
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal 1000, no discount, tax = floor(1000 * 0.1) = 100
      expect(result.totals.taxCents).toBe(100);
      expect(result.totals.totalCents).toBe(1100);
      expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
    });

    it("composes discount + async tax + shipping", async () => {
      const discountPolicy: DiscountPolicy = {
        computeDiscountCents: () => 500,
      };
      const shippingCalculator: ShippingCalculator = {
        computeShippingCents: () => 300,
      };
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockResolvedValue(0.1),
      };
      const cart = new Cart({
        discountPolicy,
        shippingCalculator,
        region: "US",
      });
      cart.add(makeProduct({ id: "x", unitPriceCents: 2000 }), 1);
      const result = await cart.checkout({ asyncTaxProvider });
      // subtotal=2000, discount=500 (clamped), discounted=1500
      // tax = floor(1500 * 0.1) = 150, shipping=300
      // total = 1500 + 150 + 300 = 1950
      expect(result.totals.subtotalCents).toBe(2000);
      expect(result.totals.discountCents).toBe(500);
      expect(result.totals.taxCents).toBe(150);
      expect(result.totals.shippingCents).toBe(300);
      expect(result.totals.totalCents).toBe(1950);
    });

    it("propagates priceFetcher rejection", async () => {
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi
          .fn()
          .mockRejectedValue(new Error("price service down")),
      };
      await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
        "price service down",
      );
    });

    it("propagates asyncTaxProvider rejection", async () => {
      const asyncTaxProvider: AsyncTaxRateProvider = {
        getRate: vi.fn().mockRejectedValue(new Error("tax service down")),
      };
      const c = new Cart();
      c.add(makeProduct({ unitPriceCents: 1000 }), 1);
      await expect(c.checkout({ asyncTaxProvider })).rejects.toThrow(
        "tax service down",
      );
    });

    it("generates default InventoryError message with available quantity", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          availableQuantity: 0,
          // no reason → default message
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.message).toContain("a"); // product id
