toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  NoTaxCalculator,
  RegionalTaxCalculator,
  AsyncTaxCalculator,
  totalLineWeightGrams,
  type AsyncTaxRateProvider,
} from "../src/tax.ts";
import type { CartLine, Product } from "../src/product.ts";

// Helper to create a product
function makeProduct(overrides: Partial<Product> = {}): Product {
  return {
    id: "p1",
    name: "Widget",
    unitPriceCents: 1000,
    ...overrides,
  };
}

function makeLine(
  productOverrides: Partial<Product> = {},
  quantity = 1,
): CartLine {
  return { product: makeProduct(productOverrides), quantity };
}

describe("NoTaxCalculator", () => {
  const calc = new NoTaxCalculator();

  it.each([
    [0, "US"],
    [1000, "US"],
    [5000, "FR"],
    [-100, "GB"],
  ])("returns 0 for taxable=%i region=%s", (taxable, region) => {
    expect(calc.computeTaxCents(taxable, region)).toBe(0);
  });
});

describe("RegionalTaxCalculator", () => {
  describe("constructor validation", () => {
    it("rejects defaultRate < 0", () => {
      expect(() => new RegionalTaxCalculator({}, -0.01)).toThrow(RangeError);
    });

    it("rejects defaultRate > 1", () => {
      expect(() => new RegionalTaxCalculator({}, 1.01)).toThrow(RangeError);
    });

    it("rejects non-finite defaultRate", () => {
      expect(() => new RegionalTaxCalculator({}, NaN)).toThrow(RangeError);
      expect(() => new RegionalTaxCalculator({}, Infinity)).toThrow(RangeError);
    });

    it("rejects out-of-range region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 1.5 }),
      ).toThrow(RangeError);
    });

    it("rejects negative region rate", () => {
      expect(
        () => new RegionalTaxCalculator({ US: -0.1 }),
      ).toThrow(RangeError);
    });

    it("accepts valid rates", () => {
      expect(
        () => new RegionalTaxCalculator({ US: 0.0875, FR: 0.2 }, 0.1),
      ).not.toThrow();
    });

    it("accepts zero and one as boundary rates", () => {
      expect(() => new RegionalTaxCalculator({ US: 0 }, 1)).not.toThrow();
    });
  });

  describe("computeTaxCents", () => {
    const calc = new RegionalTaxCalculator(
      { "US-CA": 0.0875, FR: 0.2 },
      0.05,
    );

    it.each([
      // [taxable, region, expected]
      [10000, "US-CA", 875], // 10000 * 0.0875 = 875
      [10000, "FR", 2000],
      [10000, "GB", 500], // falls back to default 5%
      [10001, "US-CA", 875], // 10001 * 0.0875 = 875.0875 → 875
      [0, "US-CA", 0],
      [-100, "FR", 0],
    ])(
      "taxable=%i region=%s → %i cents",
      (taxable, region, expected) => {
        expect(calc.computeTaxCents(taxable, region)).toBe(expected);
      },
    );

    it("uses defaultRate=0 when no default is specified", () => {
      const c = new RegionalTaxCalculator({ US: 0.1 });
      expect(c.computeTaxCents(1000, "FR")).toBe(0);
    });
  });
});

describe("AsyncTaxCalculator", () => {
  it("returns 0 for non-positive taxable", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.1,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(0, "US")).toBe(0);
    expect(await calc.computeTaxCents(-100, "US")).toBe(0);
  });

  it("computes tax using the resolved rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const calc = new AsyncTaxCalculator(provider);
    expect(await calc.computeTaxCents(10000, "US-CA")).toBe(875);
  });

  it("floors fractional cents", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 0.0875,
    };
    const calc = new AsyncTaxCalculator(provider);
    // 10001 * 0.0875 = 875.0875 → 875
    expect(await calc.computeTaxCents(10001, "US-CA")).toBe(875);
  });

  it("rejects rate < 0", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => -0.05,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("rejects rate > 1", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => 1.5,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("rejects NaN rate", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => NaN,
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(RangeError);
  });

  it("propagates provider rejection", async () => {
    const provider: AsyncTaxRateProvider = {
      getRate: async () => {
        throw new Error("service down");
      },
    };
    const calc = new AsyncTaxCalculator(provider);
    await expect(calc.computeTaxCents(1000, "US")).rejects.toThrow(
      "service down",
    );
  });
});

describe("totalLineWeightGrams", () => {
  it("returns 0 for empty lines", () => {
    expect(totalLineWeightGrams([])).toBe(0);
  });

  it("sums weight × quantity across lines", () => {
    const lines: CartLine[] = [
      makeLine({ weightGrams: 200 }, 3), // 600
      makeLine({ weightGrams: 500 }, 2), // 1000
    ];
    expect(totalLineWeightGrams(lines)).toBe(1600);
  });

  it("treats missing weightGrams as 0", () => {
    const lines: CartLine[] = [
      makeLine({}, 5), // no weight → 0
      makeLine({ weightGrams: 100 }, 2), // 200
    ];
    expect(totalLineWeightGrams(lines)).toBe(200);
  });
});

