        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.message).toContain("a"); // product id
      }
    });

    it("generates default InventoryError message without availableQuantity", async () => {
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockResolvedValue({
          available: false,
          // no availableQuantity, no reason
        }),
      };
      try {
        await cart.checkout({ inventoryChecker });
        expect.fail("should have thrown");
      } catch (err) {
        expect(err).toBeInstanceOf(InventoryError);
        const ie = err as InventoryError;
        expect(ie.message).toContain("insufficient stock");
        expect(ie.available).toBeUndefined();
      }
    });

    it("runs priceFetcher before inventoryChecker", async () => {
      const callOrder: string[] = [];
      const priceFetcher: PriceFetcher = {
        fetchPriceCents: vi.fn().mockImplementation(async () => {
          callOrder.push("price");
          return 1000;
        }),
      };
      const inventoryChecker: InventoryChecker = {
        check: vi.fn().mockImplementation(async () => {
          callOrder.push("inventory");
          return { available: true };
        }),
      };
      await cart.checkout({ priceFetcher, inventoryChecker });
      // All price fetches happen before any inventory check
      const firstInventory = callOrder.indexOf("inventory");
      const lastPrice = callOrder.lastIndexOf("price");
      expect(lastPrice).toBeLessThan(firstInventory);
    });
  });
});

